    out = models.upgrade(src)
    assert src == original
    assert out == {"version": 2, "id": 3, "title": "Cara", "work_mode": "unknown"}


def test_upgrade_v1_invalid_raises():
    src = {"id": 4, "name": "Dan", "remote": "sometimes"}
    original = copy.deepcopy(src)
    try:
        models.upgrade(src)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError")
    # input untouched even on failure
    assert src == original


def test_upgrade_v2_idempotent():
    src = {"version": 2, "id": 5, "title": "Eve", "work_mode": "remote"}
    original = copy.deepcopy(src)
    out = models.upgrade(src)
    assert out == original
    # returned an equal copy, not the same object
    assert out == src
    assert out is not src


def test_load_all_mixed():
